#!/usr/bin/env python3
# Minimal stdlib WebSocket server (RFC6455 handshake + text frames, no external libs).
# On each text message it parses {"version": "<v>"} and runs a UNION-injectable SQLite query:
#   SELECT id, version, changelog, rdate FROM releases WHERE version = '<v>'
# and replies {"result": "<col2 values joined>", "info": "<col3 joined>"}. users.password
# lives only in memory. UNION SELECT 1,<x>,3,4 surfaces <x> in "result".
import socket, threading, hashlib, base64, json, sqlite3, secrets, string, os, struct, sys
GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
PW = "".join(secrets.choice(string.ascii_lowercase + string.digits) for _ in range(8))
db = sqlite3.connect(":memory:", check_same_thread=False); lock = threading.Lock()
db.execute("CREATE TABLE releases(id INTEGER, version TEXT, changelog TEXT, rdate TEXT)")
db.execute("INSERT INTO releases VALUES (1,'0.0.2','initial','2023-01-01')")
db.execute("CREATE TABLE users(username TEXT, password TEXT)")
db.execute("INSERT INTO users VALUES ('admin',?)", (PW,))
db.commit()
def accept_key(k): return base64.b64encode(hashlib.sha1((k+GUID).encode()).digest()).decode()
def recv_frame(c):
    h = c.recv(2)
    if len(h) < 2: return None
    ln = h[1] & 0x7f; masked = h[1] & 0x80
    if ln == 126: ln = struct.unpack(">H", c.recv(2))[0]
    elif ln == 127: ln = struct.unpack(">Q", c.recv(8))[0]
    mask = c.recv(4) if masked else b"\x00\x00\x00\x00"
    data = bytearray()
    while len(data) < ln: data += c.recv(ln - len(data))
    return bytes(b ^ mask[i % 4] for i, b in enumerate(data))
def send_frame(c, payload):
    p = payload.encode(); n = len(p)
    if n < 126: hdr = struct.pack(">BB", 0x81, n)
    elif n < 65536: hdr = struct.pack(">BBH", 0x81, 126, n)
    else: hdr = struct.pack(">BBQ", 0x81, 127, n)
    c.sendall(hdr + p)
def query(v):
    with lock:
        try:
            rows = db.execute(f"SELECT id, version, changelog, rdate FROM releases WHERE version = '{v}'").fetchall()
            col2 = ",".join(str(r[1]) for r in rows if r[1] is not None)
            col3 = ",".join(str(r[2]) for r in rows if r[2] is not None)
            return {"result": col2, "info": col3}
        except Exception as e:
            return {"error": str(e)}
def handle(c):
    try:
        req = c.recv(4096).decode(errors="ignore")
        key = ""
        for line in req.split("\r\n"):
            if line.lower().startswith("sec-websocket-key:"): key = line.split(":",1)[1].strip()
        resp = ("HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
                f"Sec-WebSocket-Accept: {accept_key(key)}\r\n\r\n")
        c.sendall(resp.encode())
        while True:
            msg = recv_frame(c)
            if msg is None: break
            try: v = json.loads(msg).get("version", "")
            except Exception: v = ""
            send_frame(c, json.dumps(query(v)))
    except Exception: pass
    finally: c.close()
if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    s = socket.socket(); s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(("127.0.0.1", port)); s.listen(16)
    open(os.path.join(os.path.dirname(os.path.abspath(__file__)),"port.txt"),"w").write(str(s.getsockname()[1]))
    while True:
        c,_ = s.accept(); threading.Thread(target=handle, args=(c,), daemon=True).start()

SRVEOF
